import { photos, type PhotoName } from '../data/images';

interface PhotoProps {
  /** Key from src/data/images.ts, generated by `npm run images`. */
  name: PhotoName;
  /**
   * Required. Describe what is actually in the shot and where — "Drilled pier
   * installation on a slab foundation in Prairieville, LA" rather than
   * "foundation repair". Local specifics are the point.
   */
  alt: string;
  className?: string;
  /** Matches how wide the image renders, so the browser picks the right file. */
  sizes?: string;
  /** Set on an above-the-fold image so it is not lazy-loaded. */
  priority?: boolean;
}

/**
 * A self-hosted, responsive WebP image.
 *
 * Carries intrinsic width and height so the browser reserves the right space
 * before the file arrives, which is what keeps it from shifting the layout.
 */
export default function Photo({
  name,
  alt,
  className,
  sizes = '(max-width: 768px) 100vw, 800px',
  priority = false,
}: PhotoProps) {
  const photo = photos[name];
  return (
    <img
      src={photo.src}
      srcSet={photo.srcSet}
      sizes={sizes}
      width={photo.width}
      height={photo.height}
      alt={alt}
      loading={priority ? 'eager' : 'lazy'}
      decoding={priority ? 'sync' : 'async'}
      className={className}
    />
  );
}
